package com.nextrade.engine.strategy; import com.nextrade.engine.market.*; import com.nextrade.contracts.strategy.StrategySignal; import java.util.*; public final class StrategyEngine {private final Map<String,Strategy> strategies=new LinkedHashMap<>();public void register(Strategy s){strategies.put(s.id(),s);}public void remove(String id){strategies.remove(id);}public List<StrategySignal> onTick(MarketTick tick,List<MarketTick> history){List<StrategySignal> out=new ArrayList<>();for(Strategy s:strategies.values())s.onTick(tick,history).ifPresent(out::add);return List.copyOf(out);}public Set<String> ids(){return Set.copyOf(strategies.keySet());}}
